1	import { addMonths, addDays } from './dates.js';
2	
3	/** Billing cycles a plan can have. */
4	export const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly', WEEK: 'weekly' });
5	
6	/** Every supported cycle, as stored in the subscriptions file. */
7	export const CYCLES = Object.freeze(Object.values(CYCLE));
8	
9	/**
10	 * What a plan costs per month, in whole cents (cut to the cent).
11	 * @param {{ price: number, cycle: string }} sub
12	 * @returns {number}
13	 */
14	export function monthlyCents(sub) {
15	  if (sub.cycle === CYCLE.MONTH) return Math.floor(sub.price);
16	  if (sub.cycle === CYCLE.YEAR) return Math.floor(sub.price / 12);
17	  if (sub.cycle === CYCLE.WEEK) return Math.floor(sub.price * 52 / 12);
18	  return 0;
19	}
20	
21	/**
22	 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
23	 * Charges fall on the day of the month of the first charge (`since`), or the last day of a shorter month.
24	 * Weekly charges recur every 7 days.
25	 * @param {{ cycle: string, since: string }} sub
26	 * @param {string} today
27	 * @returns {string}
28	 */
29	export function nextCharge(sub, today) {
30	  if (sub.cycle === CYCLE.WEEK) {
31	    let n = 0;
32	    let date = sub.since;
33	    while (date < today) {
34	      n += 1;
35	      date = addDays(sub.since, n * 7);
36	    }
37	    return date;
38	  }
39	  const monthsPerCharge = sub.cycle === CYCLE.MONTH ? 1 : 12;
40	  let n = 0;
41	  let date = sub.since;
42	  while (date < today) {
43	    n += 1;
44	    date = addMonths(sub.since, n * monthsPerCharge);
45	  }
46	  return date;
